import json
from itertools import product
from fractions import Fraction

# Finite model: 3 reporters, 3 accident facts, press agent knows all facts.
# Each reporter i has told-set T_i (= what they know) and a publish flag
# can_pub[i] (whether they can actually get a story out first).
FACTS = frozenset({0, 1, 2})
REPORTERS = range(3)
subsets = [frozenset(s) for r in range(4) for s in __import__("itertools").combinations(FACTS, r)]

def scoops(i, K, can_pub, j):
    # i scoops j: i holds a fact j lacks and i can actually publish it
    return can_pub[i] and bool(K[i] - K[j])

def scoops_all(i, K, can_pub):
    return all(scoops(i, K, can_pub, j) for j in REPORTERS if j != i)

def premises_hold(T, K):
    # P1: every reporter knows exactly what the press agent told them
    p1 = all(K[i] == T[i] for i in REPORTERS)
    # P2: agent did not tell every reporter everything
    p2 = any(T[i] != FACTS for i in REPORTERS)
    return p1 and p2

def conclusion(K, can_pub):
    return any(scoops_all(i, K, can_pub) for i in REPORTERS)

# Enumerate all models
models = []
for T in product(subsets, repeat=3):
    for can_pub in product([False, True], repeat=3):
        K = list(T)
        if premises_hold(T, K):
            models.append((T, K, can_pub))

# Gap check: premises true, conclusion false, and a reporter knows strictly
# more than every other reporter (the "knows more" fact the argument notes).
gap_models = []
for T, K, can_pub in models:
    if conclusion(K, can_pub):
        continue
    knows_most = any(
        all(K[i] > K[j] for j in REPORTERS if j != i) for i in REPORTERS
    )
    if knows_most:
        gap_models.append((T, can_pub))

# Option C is consistent with the premises and the conclusion failing.
c_consistent = len(gap_models) > 0
final_answer = "C" if c_consistent else "UNSUPPORTED"

evidence = {
    "premise_models": len(models),
    "gap_models_knows_more_but_no_scoop": len(gap_models),
    "fraction_gap_models": str(Fraction(len(gap_models), max(len(models), 1))),
    "flaw": "knowing more does not imply the ability to scoop",
}

print(json.dumps({"final_answer": final_answer, "evidence": evidence}))
